/** Version à laquelle s'applique une section : les deux, la version GitHub (clé personnelle) ou la version Google Play (service IA). */
enum class PrivacyScope { ALL, GITHUB, PLAY }

class PrivacySection(val title: String, val body: String, val scope: PrivacyScope)

/** Titre de la section propre à la version GitHub qui vérifie elle-même ses mises à jour. */
const val PRIVACY_GITHUB_ONLY = "Vérification des mises à jour (version GitHub uniquement)"

/** Texte de la politique de confidentialité (même contenu que PRIVACY.md dans le dépôt). */
val PRIVACY_SECTIONS: List<PrivacySection> = listOf(
    PrivacySection(t("Qui est responsable ?"),
        t("Lifoody est édité par Fanix Studio (Mathéo Greneche) et développé avec l'assistance d'une IA. Adresse et immatriculation : voir les mentions légales sur lifoody.pages.dev. Contact (questions, exercice de tes droits, signalements) : contact.fanixstudio@gmail.com.\nLifoody existe en deux versions : la version Google Play, où l'IA passe par le service IA de Lifoody (3 essais gratuits, puis l'abonnement Lifoody Premium), et la version GitHub, gratuite, où tu utilises ta propre clé Gemini. Sauf mention contraire, ce document vaut pour les deux."), PrivacyScope.ALL),
    PrivacySection(t("Qui peut utiliser Lifoody ?"),
        t("L'app est réservée aux personnes de 15 ans et plus (âge à partir duquel on peut consentir seul au traitement de ses données en France). Les fonctions IA sont réservées aux 18 ans et plus. L'objectif « Perdre du poids » n'est pas proposé avant 18 ans, ni quand l'IMC est déjà inférieur à 18,5. Les croisements (rencontres avec des inconnus) sont réservés aux 18 ans et plus. L'abonnement Lifoody Premium (version Google Play) sert aux fonctions IA : il est donc lui aussi réservé aux 18 ans et plus."), PrivacyScope.ALL),
    PrivacySection(t("Ce qui reste sur ton téléphone"),
        t("Ton profil (âge, sexe, poids, taille, activité, objectif, habitudes, allergies), ta photo de profil, tes repas, ton emploi du temps de repas, ton sommeil, tes pas, tes pesées, ta progression (séries, niveaux, quiz), ton Nutridex et ses photos, la liste de tes amis et rencontres, ton programme sportif, tes activités GPS (tracés), les actus déjà lues, les questions de quiz déjà posées, l'eau bue, ton humeur et ton énergie du jour, ta liste de courses, le contenu de « Mon frigo », tes missions et badges, l'historique de tes conversations avec le coach (sans les photos), et tes réglages. Certaines de ces informations sont des données de santé. Elles sont chiffrées sur le téléphone (AES-256, Android Keystore), sans compte, et aucune copie n'est faite sans ton accord. Elles ne sont envoyées nulle part tant que l'IA et la sauvegarde sont désactivées et que ton profil d'amis est privé. Base légale : ton consentement explicite (case à cocher au premier lancement). Durée : tant que l'app est installée (repas : 1 an, emploi du temps : 3 mois)."), PrivacyScope.ALL),
    PrivacySection(t("Ce qui est envoyé si tu actives l'IA"),
        t("L'IA est désactivée par défaut et demande un consentement séparé (réservé aux 18 ans et plus). Dans la version Google Play, elle passe par le service IA de Lifoody (3 essais gratuits, puis l'abonnement Lifoody Premium) ; dans la version GitHub, par ta propre clé API Gemini, que tu crées toi-même chez Google. Si tu l'actives, seules les données nécessaires à chaque demande sont envoyées :\n• Analyse de photo : la photo du repas et tes allergies ; si tu as activé « Retirer du frigo après une photo de repas », aussi la liste de « Mon frigo » (noms et quantités). Si tu corriges l'analyse (« 400 g de merguez », « sans frites ») ou que tu renommes le plat, ce que tu écris et l'analyse précédente (aliments, poids, calories, sans la photo) sont envoyés pour la recalculer.\n• Objectif calorique : âge, sexe, poids, taille, activité, objectif, habitudes, allergies.\n• Idées de repas : ton objectif, les repas du jour, tes habitudes et allergies.\n• Recette : le nom du plat, tes habitudes et allergies.\n• Planning (semaine ou un seul jour) : ton objectif, tes habitudes et allergies, ton budget, le nombre de personnes et les précisions que tu écris (goûts du foyer…) ; si tu le demandes, les repas prévus pour préparer la liste de courses.\n• Prix actuels : une fois par mois au plus, une recherche Google des prix moyens en supermarché d'une liste fixe de produits courants (œufs, riz, pâtes…), sans aucune donnée personnelle, pour estimer les coûts du planning et des recettes.\n• Objectif d'eau (si l'IA est activée et que tu n'as pas choisi un objectif fixe) : âge, sexe, poids, taille, activité, objectif et apport visé, tes pas, séances et minutes de sortie d'hier, et l'objectif d'hier. Envoyé une fois par jour, automatiquement.\n• Objectif de pas (si tu choisis « Conseil de l'IA ») : âge, sexe, activité, objectif, tes pas et objectifs des 7 derniers jours. Envoyé une fois par jour, automatiquement (à la première ouverture de l'app ou au relevé des pas), tant que ce mode est choisi.\n• Liste de courses (si tu la prépares avec l'IA) : les repas prévus (noms, descriptions, ingrédients des recettes) et le nombre de personnes.\n• « Mon frigo » : pour « Que cuisiner ? », la liste de ton frigo, la photo de ton frigo ou de tes placards (si tu en prends une) et ce que tu écris, avec tes allergies, habitudes, objectif et calories restantes ; pour le ticket de caisse, seulement la photo du ticket ou des courses. Les photos sont supprimées du téléphone juste après l'analyse.\n• Programme sportif : âge, sexe, poids, taille, activité, but, niveau, matériel, et les envies et douleurs ou limites que tu écris (données de santé).\n• Questions à l'IA (sur une photo, une recette, ton programme ou une actu) : tes questions, le contexte concerné (photo et analyse, recette, programme, ou titre, extrait et lien de l'actu), tes allergies et habitudes. Pour une actu, l'IA peut faire des recherches Google (outil de recherche de Gemini) pour savoir de quoi parle l'article : Google reçoit alors les recherches que l'IA formule ; les sources et les suggestions de recherche de Google sont affichées avec la réponse. La conversation n'est pas gardée après fermeture.\n• Coach (« Parler au chef ») : tes questions, les photos que tu joins toi-même à un message (elles ne sont pas gardées), et pour personnaliser ses conseils : âge, sexe, poids, taille, activité, objectif calorique et macros, habitudes, allergies, repas du jour, pas du jour, et un résumé des 7 derniers jours (jours validés, score moyen, calories moyennes, total de pas, séances de sport, nombre et distance des sorties, évolution du poids, série en cours), ton score et ton niveau, ton programme sportif (séances, exercices, et les limites ou douleurs que tu as écrites), la liste de « Mon frigo » et les repas déjà prévus au planning pour les 7 prochains jours. Ces envois demandent ton accord, une fois, avant ta première question au coach (retiré si tu désactives l'IA). Les repas, listes de courses, changements du frigo et du programme qu'il propose ne sont appliqués que si tu appuies sur le bouton de la proposition. L'historique des conversations (sans les photos) est gardé chiffré sur ton téléphone pour pouvoir les reprendre : tu peux le désactiver, supprimer une conversation ou tout effacer à tout moment. Reprendre une conversation la renvoie à Gemini avec ta question suivante, pour que le chef garde le contexte.\nNe sont jamais envoyés : ton prénom, ton sommeil, tes photos (sauf celles que tu fais analyser ou que tu joins au coach), tes positions GPS, ton historique complet. Les réponses de l'IA sont des estimations et peuvent contenir des erreurs ; elles sont signalées comme générées par l'IA."), PrivacyScope.ALL),
    PrivacySection(t("À qui ces données sont envoyées (version GitHub)"),
        t("• Google LLC (API Gemini), directement depuis ton téléphone, avec ta propre clé API et donc sous ton propre compte Google : en créant ta clé, tu acceptes toi-même les conditions de Google, et l'éventuelle facturation se fait entre toi et Google. Google traite ces données selon les conditions de l'API Gemini ; elles peuvent être conservées temporairement par Google (par exemple pour détecter les abus) et traitées hors de l'Union européenne. Selon ces conditions (version du 28 avril 2026), pour les utilisateurs situés dans l'Espace économique européen, Google n'utilise pas les demandes ni les réponses pour améliorer ses produits, même sur son offre sans frais. Google est une entreprise américaine adhérente au cadre de protection des données UE–États-Unis (Data Privacy Framework).\n• Lifoody n'a aucun serveur : le développeur ne reçoit et ne voit aucune de tes données."), PrivacyScope.GITHUB),
    PrivacySection(t("À qui ces données sont envoyées (version Google Play)"),
        t("• Le service IA de Lifoody, édité par Fanix Studio et hébergé par Cloudflare (Cloudflare Workers, sous-traitant). Ton téléphone lui envoie chaque demande en HTTPS ; il la vérifie (taille, type de demande, essais ou abonnement), ajoute ses propres consignes de sécurité, la transmet à Google, puis te renvoie la réponse. Il n'enregistre ni tes photos, ni tes messages, ni les réponses, ni tes données de santé, et n'en tient aucun journal. Il ne garde que des compteurs d'utilisation (photos et messages du jour, essais gratuits utilisés, date de dernière utilisation), rattachés à un identifiant aléatoire créé par l'app (sans lien avec ton identité ni avec ton téléphone) ou, avec Premium, à une empreinte de ton jeton d'achat Google Play. Ces compteurs sont effacés automatiquement après 120 jours sans utilisation. Pour limiter les abus des essais gratuits, il compte aussi les essais par réseau à l'aide d'une empreinte de ton adresse IP, mélangée à une valeur secrète et au jour, effacée dès le lendemain. Cloudflare voit ton adresse IP pour acheminer la demande, comme pour tout site web ; ses serveurs peuvent se trouver hors de l'Union européenne (clauses contractuelles types de la Commission européenne, Data Privacy Framework).\n• Google LLC (API Gemini), avec la clé de Fanix Studio, sur l'offre payante de l'API : selon les conditions de l'API Gemini, Google n'utilise pas les demandes ni les réponses pour améliorer ses produits ; elles peuvent être conservées temporairement (par exemple pour détecter les abus) et traitées hors de l'Union européenne. Google ne reçoit ni ton adresse IP ni ton identifiant : il ne voit que le serveur de Lifoody. Google est une entreprise américaine adhérente au cadre de protection des données UE–États-Unis (Data Privacy Framework).\n• Google Play Integrity : avec chaque demande, l'app joint un jeton de Google Play prouvant qu'il s'agit de la vraie app Lifoody installée depuis Google Play, sur un appareil authentique ; le serveur de Lifoody le fait vérifier par Google. Ce jeton contient des informations techniques sur l'app et l'appareil, pas tes données.\nBases légales : ton consentement explicite pour l'envoi de tes données à l'IA (données de santé, RGPD art. 9.2.a) ; l'exécution du contrat (abonnement) et l'intérêt légitime (éviter les abus, maîtriser les coûts) pour les compteurs et la vérification de l'app."), PrivacyScope.PLAY),
    PrivacySection(t("Abonnement Lifoody Premium (version Google Play)"),
        t("Le paiement, l'essai gratuit, le renouvellement, la résiliation et les remboursements sont gérés par Google Play, selon ses conditions et sa politique de confidentialité : Fanix Studio ne reçoit jamais ta carte bancaire ni ton adresse e-mail. Pour savoir si ton abonnement est actif, l'app envoie au service IA le jeton d'achat fourni par Google Play ; le serveur le fait vérifier par Google (API Google Play Developer), qui répond l'état de l'abonnement et sa date de fin. Seuls cet état et une empreinte du jeton sont gardés, et revérifiés au plus tard toutes les 6 heures. Google Play transmet aussi à Fanix Studio des rapports de ventes (pays, montant, date, numéro de commande), sans aucune donnée de santé, conservés le temps exigé par la loi pour la comptabilité (10 ans). Les calculs automatiques du jour (objectifs d'eau et de pas) ne se font qu'avec Premium et ne consomment jamais d'essai gratuit."), PrivacyScope.PLAY),
    PrivacySection(t("Ta clé API (version GitHub)"),
        t("Ta clé Gemini est rangée dans un coffre à part, chiffrée par une clé de la puce de sécurité du téléphone (Android Keystore, StrongBox quand le téléphone en a une). Cette clé ne peut pas être extraite, et, si un code de verrouillage est défini sur le téléphone, elle ne fonctionne que téléphone déverrouillé (Android 9 et plus) : même avec les fichiers de l'app, personne ne peut lire ta clé API, ni toi, ni le développeur. Elle est saisie dans un champ de mot de passe (les claviers ne l'apprennent normalement pas), et elle est retirée du presse-papiers si tu l'as collée (Android 9 et plus). Elle est conservée lors des mises à jour de l'app et envoyée uniquement à Google, en HTTPS (aucun certificat ajouté à la main n'est accepté), dans l'en-tête des requêtes. Elle n'apparaît dans aucune exportation ni sauvegarde, et « Effacer toutes mes données » détruit aussi la clé du coffre."), PrivacyScope.GITHUB),
    PrivacySection(t("Scan de code-barres (sans IA)"),
        t("Le code-barres est lu sur le téléphone avec ML Kit (modèle intégré, aucune image envoyée). Seul le numéro du code-barres est envoyé à Open Food Facts (association française, base de données ouverte) pour obtenir les valeurs nutritionnelles. Open Food Facts voit ton adresse IP, comme n'importe quel site web. ML Kit (le lecteur de code-barres et de QR code de Google) envoie aussi à Google des données techniques de diagnostic : modèle et système du téléphone, version de l'app, identifiant d'installation et mesures de performance, sans aucune image ni aucun code lu."), PrivacyScope.ALL),
    PrivacySection(t("Les pas"),
        t("Si tu actives le suivi des pas, ils sont comptés sur le téléphone : par le capteur de pas (relevé toutes les 15 minutes, lecture d'un simple compteur) ou, si tu le choisis, en lecture seule dans Health Connect (pas enregistrés par Samsung Health, Google Fit, une montre…). Lifoody ne lit que le nombre de pas, rien d'autre, Ils restent sur le téléphone, sauf : avec l'IA activée, tes pas du jour et de la semaine pour le coach, tes pas d'hier pour l'objectif d'eau et tes pas des 7 derniers jours si tu demandes un objectif à l'IA ; et, si ton profil d'amis est public, le total de tes pas de la semaine pour tes amis. Tu peux couper le suivi dans Paramètres › Pas."), PrivacyScope.ALL),
    PrivacySection(t("Activités GPS (course, marche, vélo)"),
        t("Ta position n'est utilisée que pendant une activité que tu lances toi-même (autorisation « pendant l'utilisation »). Tant qu'elle est en cours, une notification l'indique et le suivi continue écran éteint. Le tracé, le temps, la distance, la vitesse et le dénivelé sont enregistrés chiffrés sur ton téléphone, jamais envoyés, et inclus dans ta sauvegarde chiffrée si tu l'as activée. Tu peux supprimer une activité à tout moment. Pas de localisation en arrière-plan."), PrivacyScope.ALL),
    PrivacySection(t("Carte et clubs"),
        t("Le fond de carte vient d'OpenFreeMap (données © contributeurs OpenStreetMap, © OpenMapTiles) : comme pour toute appli de carte, le serveur voit ton adresse IP et la zone affichée. Pour proposer des boucles ou un itinéraire vers une destination, l'app télécharge chez OpenFreeMap les tuiles de carte de la zone concernée (les mêmes que celles de la carte, dès que tu ouvres le panneau des boucles) et calcule le chemin sur ton téléphone ; ces tuiles restent au plus 30 jours dans le cache de l'app. Si elles ne sont pas disponibles, et quand tu cherches des clubs, les coordonnées de la zone sont envoyées à l'API Overpass d'OpenStreetMap (serveur public géré par une association allemande). Pour le dénivelé (profil d'un itinéraire, « Éviter les côtes », « Dénivelé »), l'app télécharge les tuiles d'altitude ouvertes « Terrain Tiles » (données publiques hébergées par Amazon Web Services) de la zone concernée : le serveur voit ton adresse IP et les numéros de ces tuiles ; elles restent au plus 60 jours dans le cache de l'app. Quand tu cherches un lieu (ville, adresse), le texte tapé et la zone affichée sont envoyés à Nominatim (OpenStreetMap) ; les résultats sont gardés un jour en mémoire pour ne pas redemander la même chose, et une fois par jour au plus l'app vérifie sur la page GitHub du projet que ce service peut toujours être utilisé (GitHub voit ton adresse IP). Le guidage, le recalcul de l'itinéraire, ta vitesse moyenne et l'heure d'arrivée sont calculés sur ton téléphone. Les cartes hors ligne sont téléchargées depuis OpenFreeMap pour la seule zone que tu choisis (pour annoncer leur taille, l'app demande d'abord la taille de quelques tuiles de cette zone, sans les télécharger) ; en qualité « Complète », les rues et les tuiles d'altitude (Terrain Tiles) de cette zone sont aussi enregistrées, pour calculer itinéraires et dénivelé sans réseau. Tout reste sur ton téléphone jusqu'à ce que tu supprimes la zone, ou tes données. Les informations des clubs (tarifs, horaires, site) viennent d'OpenStreetMap et peuvent être incomplètes : vérifie-les auprès du club."), PrivacyScope.ALL),
    PrivacySection(t("Notifications du coach"),
        t("Désactivées tant que tu ne les as pas acceptées (à l'inscription ou dans Paramètres › Notifications). Le bilan du matin, le mot de midi, le rappel du soir et le bilan de la semaine sont préparés sur ton téléphone, sans réseau ni IA et sans aucun serveur. Sur l'écran verrouillé, seul « Un message du chef » s'affiche, sans tes chiffres ; si le verrouillage par empreinte est activé, les chiffres ne s'affichent nulle part dans les notifications. Tu peux couper chaque notification à tout moment."), PrivacyScope.ALL),
    PrivacySection(t("Actus du jour"),
        t("Tu choisis tes thèmes (alimentation, sport, santé et bien-être, insolite, anecdote du jour), ou aucun : les actus sont alors désactivées. Une fois par jour (à l'ouverture de l'accueil ou des actus), Lifoody lit les flux RSS publics de franceinfo, Sciences et Avenir, Futura, de l'Anses et de Santé publique France pour choisir des actus sur tes thèmes. Ces sites voient ton adresse IP, comme pour n'importe quel site ; aucune autre donnée ne leur est envoyée. Seul le titre est affiché (avec un court extrait pour l'Anses et Santé publique France) ; l'article complet s'ouvre chez la source, dans ton navigateur, seulement si tu le touches. La liste des actus déjà montrées reste chiffrée sur ton téléphone pour ne jamais te remontrer la même. Sans connexion, l'app affiche à la place des anecdotes vérifiées intégrées.\n• Résumé du chef (si l'IA est activée) : pour un article de l'Anses ou de Santé publique France, l'app lit la page publique de l'article et envoie son titre et son texte à Google Gemini (avec ta clé, ou via le service IA de Lifoody dans la version Google Play) pour le résumer. Aucune donnée te concernant n'est envoyée. Le résumé n'est pas gardé."), PrivacyScope.ALL),
    PrivacySection(t("Widgets"),
        t("Si tu ajoutes un widget Lifoody sur ton écran d'accueil, il affiche le chef, ta série, tes calories et tes pas ; le grand widget montre aussi l'eau, les protéines et ton prochain repas prévu au planning. Tout est calculé sur le téléphone. Les widgets sont visibles par toute personne qui voit ton écran d'accueil : si le verrouillage par empreinte est activé, ils n'affichent aucun chiffre de santé."), PrivacyScope.ALL),
    PrivacySection(t("Le Nutridex"),
        t("Quand l'IA reconnaît un aliment sur une photo, il se débloque dans ton Nutridex avec une petite vignette de ta photo. Un produit scanné par code-barres débloque aussi les aliments de son nom et de ses premiers ingrédients (liste d'Open Food Facts, comparée sur ton téléphone, sans IA), avec une vignette de la photo de l'emballage. Ces vignettes sont chiffrées sur ton téléphone et ne sont jamais partagées : tes amis ne voient, si tu l'autorises, que la liste des aliments découverts."), PrivacyScope.ALL),
    PrivacySection(t("Amis : Tap to Sync, QR code et croisements"),
        t("Ton profil est privé par défaut. Si tu le rends public, tu choisis un pseudo et ce que tu partages (niveau, série, liste du Nutridex, bilan de la semaine pour le défi entre amis : jours validés, total de pas et XP de la semaine). Ces informations forment une « carte » signée par ton téléphone, transmise directement à l'autre téléphone, sans aucun serveur : en collant les téléphones (NFC), en scannant ton QR code, avec les croisements, ou par un message que tu envoies toi-même (« Partager ma carte ») : la carte passe alors par la messagerie que tu choisis (WhatsApp, SMS…), selon ses propres conditions, jamais par un serveur Lifoody. Ce message contient un lien vers une page d'invitation statique hébergée par GitHub Pages : ta carte est dans la partie du lien après « # », que le navigateur n'envoie jamais au serveur ; GitHub voit seulement l'adresse IP de la personne qui ouvre la page (sans statistique ni cookie). La carte que tu donnes par NFC, QR code ou lien contient aussi une clé secrète, qui permet à cette personne de te reconnaître lors des croisements : ne la partage qu'avec des amis. Ne sont jamais partagés : ton poids, tes repas, ton sommeil, tes photos, ton âge.\n• Croisements (désactivés par défaut, 18 ans et plus, Android 12+) : tant qu'ils sont actifs, une notification discrète l'indique (Android l'impose) et les téléphones Lifoody à quelques mètres lisent ta balise en Bluetooth (relue au plus toutes les 15 minutes) ; tes amis y retrouvent ta carte à jour et tes encouragements. Une notification te prévient quand tu croises quelqu'un pour la première fois ou que tu le recroises. L'app ne demande pas la localisation. Ta carte n'est jamais diffusée en clair : ton téléphone diffuse un identifiant aléatoire qui change toutes les 15 minutes, ton niveau (si tu le partages) et ta carte chiffrée, que seuls tes amis peuvent ouvrir. Un inconnu voit seulement « un joueur niveau 12 », sans pseudo, et ne peut pas te reconnaître d'un endroit à l'autre ni te suivre. Tu peux masquer et bloquer une personne.\n• Les cartes que tu reçois sont gardées chiffrées sur ton téléphone ; retire ou bloque une personne pour effacer la sienne.\n• Les encouragements sont des messages tout prêts, sans texte libre. Quand une carte reçue contient un encouragement pour toi, une notification te prévient (préparée sur ton téléphone, sans serveur).\nBase légale : ton consentement (activation du profil public). Tu peux le retirer à tout moment en le rendant privé."), PrivacyScope.ALL),
    PrivacySection(t(PRIVACY_GITHUB_ONLY),
        t("Dans la version téléchargée depuis GitHub, et tant que l'option est activée (elle l'est par défaut ; Paramètres › Mises à jour), l'app demande à GitHub, à chaque ouverture, quelle est la dernière version publiée ; si tu appuies sur « Installer », elle télécharge l'APK depuis la page officielle du projet. GitHub voit alors ton adresse IP ; aucune autre donnée n'est envoyée. Avant l'installation, l'app vérifie l'empreinte du fichier et qu'il est signé avec la même clé que l'app installée, puis Android te demande de confirmer. Rien n'est installé sans ton accord. La version Google Play n'a pas cette fonction : ses mises à jour passent par le Play Store."), PrivacyScope.GITHUB),
    PrivacySection(t("Sauvegarde chiffrée (si tu l'actives)"),
        t("Désactivée par défaut. Si tu l'actives (Paramètres › Sauvegarde chiffrée), Lifoody écrit une copie de tes données dans le fichier que tu choisis (par exemple sur Google Drive ou dans Téléchargements), puis la met à jour quand tu quittes l'app après un changement. Le fichier est chiffré (AES-256-GCM) avec une clé tirée de ton mot de passe (PBKDF2, 310 000 itérations) : sans le mot de passe, il est illisible, y compris pour le service qui le stocke et pour le développeur. Le mot de passe n'est jamais enregistré ; seule la clé qui en est tirée est gardée, chiffrée par l'Android Keystore, pour refaire la copie automatiquement. La sauvegarde ne contient ni ta clé API, ni ton consentement IA, ni tes réglages de sécurité. Si tu choisis un service en ligne, c'est lui qui stocke le fichier chiffré, selon ses propres conditions. Mot de passe oublié = sauvegarde perdue."), PrivacyScope.ALL),
    PrivacySection(t("Signaler un contenu de l'IA"),
        t("Sous chaque réponse de l'IA, un bouton « Signaler » te permet de prévenir le développeur d'un contenu faux, dangereux ou choquant. Rien n'est envoyé automatiquement : l'app prépare un e-mail que tu peux relire et modifier avant de l'envoyer toi-même depuis ta messagerie. Il contient le motif choisi et le texte signalé, jamais tes données de santé. Cet e-mail est utilisé uniquement pour traiter le signalement, puis supprimé."), PrivacyScope.ALL),
    PrivacySection(t("Retirer ton consentement"),
        t("Tu peux désactiver l'IA à tout moment dans Paramètres › Intelligence artificielle. Plus rien n'est alors envoyé. Ce retrait ne remet pas en cause les demandes faites avant. Désactiver l'IA ne résilie pas l'abonnement Lifoody Premium : pour cela, va dans Google Play › Paiements et abonnements (ou Paramètres › Intelligence artificielle › Gérer mon abonnement). Pour retirer ton accord au traitement de tes données de santé, efface tes données (Paramètres) ou désinstalle l'app."), PrivacyScope.ALL),
    PrivacySection(t("Le sommeil"),
        t("La détection automatique utilise la Sleep API des services Google Play, calculée sur le téléphone. Lifoody ne reçoit que les heures de coucher et de réveil, stockées localement et jamais envoyées."), PrivacyScope.ALL),
    PrivacySection(t("Tes droits (RGPD)"),
        t("Accès et portabilité : Paramètres › Mes données et confidentialité › Exporter mes données (fichier protégé par mot de passe, conseillé, ou fichier lisible JSON). Rectification : Moi › Mon objectif et mes infos. Effacement : Paramètres › Mes données et confidentialité › Effacer toutes mes données (ou désinstaller l'app) ; un fichier de sauvegarde que tu as créé est à supprimer toi-même là où tu l'as rangé. Retrait du consentement : interrupteur IA, profil privé (Amis). Tes données sont sur ton téléphone (et dans ta sauvegarde chiffrée, si tu en as créé une) : le développeur n'en a aucune copie. Dans la version Google Play, le service IA ne garde que des compteurs d'utilisation liés à un identifiant aléatoire : « Effacer toutes mes données » remplace cet identifiant, et les anciens compteurs sont effacés automatiquement après 120 jours. Pour toute question : contact.fanixstudio@gmail.com. Tu peux aussi adresser une réclamation à la CNIL (cnil.fr)."), PrivacyScope.ALL),
    PrivacySection(t("Ce que Lifoody ne fait pas"),
        t("Aucune donnée n'est vendue, louée ou partagée à des fins publicitaires. Pas de publicité, pas de traceur, pas de profilage marketing. Le développeur ne reçoit ni ne voit tes données de santé : la version GitHub n'utilise aucun serveur, et le service IA de la version Google Play transmet tes demandes sans les enregistrer."), PrivacyScope.ALL),
    PrivacySection(t("Important"),
        t("Lifoody est une application de bien-être. Ce n'est pas un dispositif médical : elle ne permet pas de diagnostiquer, traiter, guérir ou prévenir une maladie. Les calories, objectifs et conseils (calculés ou donnés par l'IA) sont des estimations indicatives. Demande l'avis d'un médecin ou d'un professionnel de santé avant de changer ton alimentation, surtout en cas de maladie, de grossesse ou de troubles du comportement alimentaire."), PrivacyScope.ALL)
)

/** Sections qui concernent cette version de l'app. */
fun privacySectionsForThisApp(): List<PrivacySection> = PRIVACY_SECTIONS.filter {
    when (it.scope) {
        PrivacyScope.ALL -> true
        PrivacyScope.PLAY -> BuildConfig.AI_RELAY
        PrivacyScope.GITHUB -> !BuildConfig.AI_RELAY && (BuildConfig.SELF_UPDATE || it.title != t(PRIVACY_GITHUB_ONLY))
    }
}

@Composable
fun PrivacyScreen(onBack: () -> Unit) {
    BackHandler(onBack = onBack)
    Surface(Modifier.fillMaxSize(), color = MaterialTheme.colorScheme.background) {
        ScreenColumn {
            SubScreenHeader(t("Confidentialité"), onBack)
            Text(
                t("Version 0.18.0 · mise à jour le 9 octobre 2026"),
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
            privacySectionsForThisApp().forEach { s ->
                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                    Text(s.title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Medium)
                    Text(s.body, style = MaterialTheme.typography.bodyMedium)
                }
            }
        }
    }
}
